mcp__Remote_Desktop_Commander__review_device_call(args: {
// Name of the Desktop Commander tool, for example start_process.
tool_name: "get_config" | "set_config_value" | "read_file" | "read_multiple_files" | "write_file" | "write_pdf" | "create_directory" | "list_directory" | "move_file" | "start_search" | "get_more_search_results" | "stop_search" | "list_searches" | "get_file_info" | "edit_block" | "start_process" | "read_process_output" | "interact_with_process" | "force_terminate" | "list_sessions" | "list_processes" | "kill_process" | "get_usage_stats" | "get_recent_tool_calls",
// The call's exact arguments, unchanged, including deviceId if it had one.
arguments: { [key: string]: any },
// Shown to the user above the call. One short, plain sentence for a non-technical user: what this call does for them, starting with 'I'm'. For example: 'I'm checking your Tailscale IP and looking for Tailscale files in your app folders.' Do not say that the call was stopped, explain the Run and Cancel buttons, or say whether the call is safe; the panel says those.
summary: string, // maxLength: 500
// Required whenever you pass client_error. One short, plain sentence after the summary with your best guess of why the client stopped the call. For example: 'It was likely stopped because it searches private app data for network addresses.'
likely_reason?: string, // maxLength: 300
// The client's message, if it said it stopped the call before sending it.
client_error?: string, // maxLength: 1000
}): Promise<{ tool_name: string, summary: string, likely_reason: string | null, device_id: string | null, after_client_error: boolean, status: "awaiting_user" }>;
